messages.content:
{
  "message": "Thanks for checking. “No SIM card detected” explains the No Service. The most likely cause is the SIM not making proper contact. Let’s reseat it and recheck. If the phone still can’t see the SIM after that and a reboot, we’ll escalate.",
  "what_im_thinking_and_doing": "Because the phone reports no SIM, network settings and account status won’t matter until the device actually detects the SIM. We’ll focus on reseating first, then verify detection. In parallel, once you share your account info, I’ll check your line status on our side.",
  "steps_for_you_now": [
    "Reseat the SIM card (use the reseat_sim_card action): Power the phone off, eject the SIM tray, remove the SIM, check orientation, reinsert it firmly so it sits flat, and fully close the tray. Then power the phone back on.",
    "Wait ~10 seconds after boot, then check SIM status again (check_sim_status) and tell me what it shows.",
    "If it still says Missing/No SIM: Please reboot once more (reboot_device), wait 10 seconds after it comes back up, and check SIM status again.",
    "If SIM now shows Active: Check overall network (check_network_status) to see signal bars, network type, and whether mobile data is enabled. If you see bars, try a test call."
  ],
  "important_notes": [
    "If the SIM status changes to Locked at any point, don’t try PIN/PUK guesses—tell me and I’ll escalate for SIM security help."
  ],
  "what_to_tell_me_next": [
    "The exact result of check_sim_status after reseating (Active, Missing, or Locked).",
    "If Active, the results of check_network_status (signal strength and network type) and whether calls/data work.",
    "Your phone model (iPhone/Android and model) and your city/state."
  ],
  "account_verification_needed": {
    "why": "To rule out any suspension or provisioning issues once the SIM is detected.",
    "provide_one_of": [
      "Phone number of the affected line",
      "Customer ID",
      "Full name AND date of birth (YYYY-MM-DD)"
    ]
  }
}

