{
  "message": "I can help with that. First, I need to identify your account so I can check the line’s status (e.g., any suspension or SIM/activation issues). Then we’ll run a few quick checks on your phone to isolate the cause.",
  "why_im_asking": "No Service can be caused by line suspension (overdue bill or contract end), Airplane Mode, SIM problems, or incorrect settings. Verifying your line status lets me rule out account-side causes before we troubleshoot the device.",
  "what_i_need_from_you": {
    "one_of": [
      "The phone number of the affected line",
      "Your customer ID",
      "Your full name AND date of birth (YYYY-MM-DD)"
    ],
    "extra_context": [
      "Your current city/state or ZIP (helps determine if this is location-specific)",
      "Is this happening everywhere you go or only in one place?",
      "Did this start after any changes (travel, SIM swap, new phone, software update)?"
    ]
  },
  "while_we_verify_account": {
    "quick_checks_on_phone": [
      "Check the status bar: do you see an airplane icon, or does it say No Service with 0 bars?",
      "If Airplane Mode is ON, turn it OFF. If it’s OFF, toggle it ON, wait 10 seconds, then OFF again.",
      "Confirm Mobile Data is ON.",
      "If you recently removed/reinserted the SIM, let me know. If the phone shows SIM Missing/Locked, tell me what it says exactly."
    ],
    "if_comfortable": [
      "Reboot the device now (this refreshes network registration)."
    ]
  }
}

