messages.content:
{
  "thought_process": "Your phone shows Mobile Data is OFF and it’s connected to a 2G network. 2G is too slow for modern data needs, and with data OFF you won’t get internet. Since you’re in France, I already enabled roaming on your line from our side. Now we need to: (1) turn ON Mobile Data on your phone, (2) enable Data Roaming on your phone, and (3) set your phone to prefer 4G/5G. Then we’ll verify and test speed.",
  "next_steps": [
    {
      "step": "Turn ON Mobile Data",
      "do": "Run toggle_data to enable mobile data.",
      "then": "Run check_network_status and tell me the output (signal strength, network type, mobile data, data roaming)."
    },
    {
      "step": "Enable Data Roaming on the phone",
      "do": "Run toggle_roaming to turn Data Roaming ON.",
      "then": "Run check_network_status again and share the output."
    },
    {
      "step": "Prefer the fastest network",
      "do": "Run check_network_mode_preference. If it is 2G/3G or anything other than 4g_5g_preferred, run set_network_mode_preference with mode=\"4g_5g_preferred\".",
      "then": "Run check_status_bar and confirm if it now shows 4G or 5G (and how many bars)."
    },
    {
      "step": "Test your speed",
      "do": "Run run_speed_test.",
      "then": "Share the result (very poor/poor/fair/good/excellent)."
    },
    {
      "step": "If speed is still poor after the above",
      "do": [
        "Run check_data_restriction_status. If Data Saver is ON, run toggle_data_saver_mode to turn it OFF.",
        "Run check_vpn_status. If a VPN is connected, run disconnect_vpn."
      ],
      "then": "Run run_speed_test again and share the result."
    },
    {
      "step": "If data still doesn’t work or remains very slow",
      "do": "Run check_apn_settings. If it shows incorrect/missing settings, run reset_apn_settings, then run reboot_device.",
      "then": "After reboot, run run_speed_test and share the result."
    }
  ],
  "what_to_send_me": [
    "The outputs of check_network_status after Step 1 and Step 2.",
    "The output of check_status_bar after Step 3.",
    "The result of run_speed_test after Step 4 (and again if we do Step 5 or 6)."
  ]
}

