messages.content:
{
  "summary": "I can help get your mobile data working fast while you’re roaming in France. We’ll check your account/line settings (roaming enablement, data balance/limits) and optimize your phone’s settings for the best possible speed.",
  "reasoning": "Roaming issues are most often caused by (1) data roaming not enabled on the line or on the phone, (2) running out of plan data, (3) restrictive phone settings like VPN/Data Saver, or (4) suboptimal network mode. We’ll verify your account first, then adjust device settings and measure speed.",
  "account_verification_request": {
    "note": "To access your line, I need to identify your account.",
    "provide_one_of": [
      "Phone number (recommended)",
      "Customer ID",
      "Full name AND date of birth (YYYY-MM-DD)"
    ]
  },
  "permissions_request": [
    "Do I have your permission to check if international roaming is enabled on your line and enable it at no cost if it’s currently off?"
  ],
  "additional_questions": [
    "Which phone number/line is having the issue (if you have multiple)?",
    "Are you using our SIM/eSIM in the same device you normally use?",
    "Do you currently have any VPN turned on?",
    "Are you connected to Wi‑Fi right now, or relying purely on mobile data?",
    "Roughly where in France are you (city/area)? This can help us understand signal conditions."
  ],
  "on_device_steps": [
    {
      "step": 1,
      "action": "check_status_bar()",
      "instructions": "Look at your status bar.",
      "report_back": [
        "Is Airplane Mode showing?",
        "Signal strength (No Signal / 1-4 bars)",
        "Network type shown (5G/4G/LTE/3G/2G)"
      ]
    },
    {
      "step": 2,
      "action": "check_network_status()",
      "instructions": "Confirm Mobile Data is ON and Data Roaming is ON.",
      "if_needed": [
        "toggle_data(on)",
        "toggle_roaming(on)"
      ],
      "report_back": [
        "Mobile Data: On/Off",
        "Data Roaming: On/Off",
        "Signal strength reading"
      ]
    },
    {
      "step": 3,
      "action": "check_vpn_status() and check_data_restriction_status()",
      "instructions": "If a VPN is connected, disconnect it. If Data Saver is ON, turn it OFF.",
      "if_needed": [
        "disconnect_vpn()",
        "toggle_data_saver_mode(off)"
      ],
      "report_back": [
        "VPN: Connected/Disconnected",
        "Data Saver: On/Off"
      ]
    },
    {
      "step": 4,
      "action": "check_network_mode_preference()",
      "instructions": "Ensure preferred network is modern.",
      "if_needed": [
        "set_network_mode_preference(\"4g_5g_preferred\")"
      ],
      "report_back": [
        "Current preferred mode before change",
        "Preferred mode after change"
      ]
    },
    {
      "step": 5,
      "action": "toggle_airplane_mode()",
      "instructions": "Turn Airplane Mode ON for ~10 seconds, then OFF to re-register to the local network."
    },
    {
      "step": 6,
      "action": "run_speed_test()",
      "instructions": "Test over mobile data (turn off Wi‑Fi during the test).",
      "report_back": [
        "Speed result category (very poor/poor/fair/good/excellent)",
        "Whether pages/apps now load normally"
      ]
    },
    {
      "step": 7,
      "action": "If still no data or very poor: reboot_device()",
      "instructions": "Restart your phone and re-test."
    }
  ],
  "what_i_will_do_after_verification": [
    "Check your line status and confirm international roaming is enabled; enable it if needed.",
    "Check your current plan and this cycle’s data usage to see if you’ve hit the data limit.",
    "If you’re out of data, I’ll offer options: refuel up to 2GB immediately (priced per your plan) or change to a plan with more data.",
    "Verify there are no billing/suspension issues impacting service."
  ],
  "next": "Please share one form of identification (phone number, customer ID, or full name + DOB), confirm permission for me to enable roaming if it’s off, and start the on-device steps. Send me the readouts so I can interpret them and proceed on the account side."
}

