messages.content:
{
  "message": "Thanks for checking Airplane Mode. Since you still see “No Signal” and data is disabled, the most likely causes are: (1) the SIM isn’t being detected or is locked, (2) the line is suspended on the account, or (3) a network setting issue. I’ll verify your line status while we run a quick SIM/network check on your phone.",
  "why_these_steps": "If the SIM is missing/locked, the phone cannot register to the network at all. If the account/line is suspended, service is blocked. If settings are off (e.g., wrong network mode/APN), the phone won’t attach to the network.",
  "need_verification": "To check your line status, please share the phone number for the line with no service. If you don’t have it, provide your full name and date of birth (YYYY-MM-DD).",
  "questions": [
    "Are you currently traveling outside your usual area or abroad?",
    "Did anything change recently (new phone/SIM, software update, physical damage, SIM swap)?"
  ],
  "next_steps_on_device": [
    {
      "step": "Check SIM status",
      "how": "Settings > Network & Internet (or Cellular) > SIMs > tap your SIM > Status. On iPhone: Settings > Cellular > SIMs. Tell me whether it shows Active/Ready, Missing/Not detected, or Locked (PIN/PUK)."
    },
    {
      "step": "If SIM shows Missing/Not detected",
      "how": "Power off the phone. Eject the SIM tray, gently reinsert the SIM (gold contacts facing down, aligned), then power on and re-check SIM status. If you use an eSIM, skip reseating and just reboot."
    },
    {
      "step": "If SIM shows Locked",
      "how": "Do not guess the PIN/PUK. Tell me exactly what it says so I can assist. Repeated attempts can permanently lock the SIM."
    },
    {
      "step": "If SIM shows Active but still No Signal",
      "how": "Check network mode: Settings > Mobile Network > Preferred network type. Ensure 4G/5G preferred (not 2G/3G only)."
    },
    {
      "step": "Reboot",
      "how": "Restart the phone after the above checks to refresh the network registration."
    }
  ],
  "what_to_reply_with": [
    "Your phone number (or full name + DOB for verification).",
    "SIM status result (Active / Missing / Locked).",
    "Preferred network mode setting (e.g., 5G/4G preferred).",
    "Whether you are traveling/roaming.",
    "Any recent changes (new device/SIM, software update, drop/damage)."
  ]
}

