messages.content:
{
  "message": "Got it—“No SIM card detected” points to the phone not reading the SIM. Let’s reseat the SIM and reboot to rule out a tray/contacts issue. If you use an eSIM (no physical card), just reboot and re-check.",
  "why_these_steps": "A slightly misaligned or dirty SIM/tray is the most common cause of a “No SIM” message. Reseating cleans/re-aligns contacts; the reboot refreshes the radio and registration.",
  "steps": [
    {
      "scenario": "Physical SIM",
      "actions": [
        "Power the phone OFF completely.",
        "Eject the SIM tray (use the SIM tool/paperclip).",
        "Remove the SIM, gently wipe the gold contacts with a clean, dry cloth (no liquids), and ensure there’s no dust in the tray/slot.",
        "Reinsert the SIM in the correct orientation (gold contacts facing down on most phones), ensure it sits flat and the tray closes flush—don’t force it.",
        "Power the phone back ON."
      ]
    },
    {
      "scenario": "eSIM (no physical card)",
      "actions": [
        "Restart the phone.",
        "After restart, open Settings > Cellular/Mobile Network > SIMs and confirm the eSIM line shows as Active/On."
      ]
    }
  ],
  "what_to_check_after": [
    "Open Settings > Cellular/Mobile Network > SIMs (or SIM status) and tell me if it now shows Active/Ready, Missing/Not detected, or Locked.",
    "Also let me know if the status bar now shows any signal bars or a network type (4G/5G)."
  ],
  "optional_isolation_if_still_missing": [
    "If available: try your SIM in another phone OR try a different known‑working SIM in this phone. This helps tell us if the issue is the SIM card or the phone’s SIM reader."
  ],
  "need_verification": "While you try the above, please share the phone number for this line (or your full name + DOB in YYYY-MM-DD) so I can check the line’s status on our side.",
  "questions": [
    "Is your line using a physical SIM or an eSIM?",
    "Did the phone experience any drop/water exposure recently?",
    "Have you changed phones or SIMs in the last few days?"
  ],
  "what_to_reply_with": [
    "Phone number (or full name + DOB).",
    "Whether it’s a physical SIM or eSIM.",
    "Result after reseating/rebooting: SIM status (Active/Missing/Locked) and whether signal returned.",
    "If you performed the isolation test, what happened?"
  ]
}

