      ]
    }
  ],
  "what_to_share": [
    "Your phone type (iPhone or Android).",
    "The exact message or state after you try to join post-reboot (e.g., Connected, Incorrect password, Authentication error, Saved, or not connected).",
    "The result of connecting to a Guest network or another known-good Wi‑Fi/hotspot.",
    "The latest check_wifi_status output."
  ],
  "note": "Your MMS over mobile data is already working, so you can continue using your phone while we sort the Wi‑Fi join. Once connected to Wi‑Fi, you may turn Wi‑Fi Calling back ON if you use it."
}

