messages.content:
{
  "summary": "Your phone shows excellent 5G signal and mobile data is ON, but the speed test reports “No Connection.” That combination usually points to a configuration/provisioning issue rather than signal strength. The most common causes are: incorrect APN settings, an active VPN blocking traffic, a temporary data toggle glitch, the SIM not being recognized properly, or a line/account restriction (suspension or data cap) on the carrier side.",
  "assurance": "Nothing below will delete or affect your photos or personal content. We’re only adjusting connectivity settings and doing standard checks.",
  "my_plan_and_reasoning": [
    "On-device checks first to rule out VPN, data toggle glitches, APN misconfiguration, or SIM issues—these are the fastest fixes when signal is good but data won’t pass.",
    "In parallel, I need to identify your account so I can verify line status, data usage vs plan limit, and roaming enablement. If the line is suspended or you’ve hit the data cap, data will not work even with full bars."
  ],
  "next_steps_on_device": [
    {
      "step": "Check VPN status",
      "why": "An active VPN can block or slow mobile data.",
      "how": "Use check_vpn_status. If it shows VPN is connected, please disconnect it using disconnect_vpn and test again after step 4."
    },
    {
      "step": "Toggle mobile data",
      "why": "Refreshing the data session often clears a stalled connection.",
      "how": "Use toggle_data to turn Mobile Data OFF, wait 10 seconds, then toggle_data to turn it ON again. Keep Wi‑Fi OFF for testing."
    },
    {
      "step": "Verify APN settings",
      "why": "Incorrect APN (especially MMSC/APN name) can yield ‘No Connection’ despite good signal.",
      "how": "Run check_apn_settings. If it shows Incorrect or MMSC URL missing, use reset_apn_settings, then use reboot_device to restart the phone so the new settings apply. After reboot, ensure Wi‑Fi is OFF and Mobile Data is ON."
    },
    {
      "step": "Check SIM status",
      "why": "If the SIM isn’t recognized properly, data can fail even with bars.",
      "how": "Run check_sim_status. If it shows Missing, use reseat_sim_card and then reboot_device. If it shows Locked (PIN/PUK), tell me—I'll arrange next steps with a human agent to assist with SIM security."
    },
    {
      "step": "Retest speed",
      "why": "To confirm whether the above fixed the issue.",
      "how": "Run run_speed_test and tell me the category (unknown/very poor/poor/fair/good/excellent). Keep Wi‑Fi OFF during the test."
    }
  ],
  "info_needed_from_you": {
    "account_identification": "Please provide one of: the phone number of the affected line (preferred), your customer ID, or your full name and date of birth (YYYY-MM-DD).",
    "travel_status": "Are you currently outside your usual coverage area or traveling internationally?",
    "data_usage_estimate": "Do you know roughly how much data you’ve used this billing cycle?",
    "vpn_usage": "Do you normally use a VPN? If yes, was it connected just now?"
  },
  "what_i_will_check_on_our_side_once_identified": [
    "Line status (ensure not suspended).",
    "Current cycle data usage vs your plan’s data limit (if exceeded, we can add data or change plans as you prefer).",
    "Roaming enablement (if you’re traveling and it’s off, I’ll enable it at no cost)."
  ]
}

