messages.content:
{
  "message": "Thanks for checking. Since your phone says “No SIM card detected,” the device cannot attach to any network, so MMS cannot work yet. The next best step is to reseat the SIM to restore detection.",
  "thought_process": [
    "MMS needs cellular service and mobile data. If the SIM isn’t detected, the phone can’t register on any network.",
    "Reseating the SIM fixes most ‘SIM missing’ cases caused by a slightly misaligned or dusty contact."
  ],
  "steps_now_reseat_sim": [
    {
      "step": 1,
      "title": "Power off the phone",
      "why": "Prevents damage and ensures the SIM is read fresh at startup."
    },
    {
      "step": 2,
      "title": "Remove and reinsert the SIM",
      "instructions": [
        "Use the SIM eject tool (or a small paperclip) to eject the SIM tray.",
        "Gently remove the SIM. Check orientation (diagonal notch corner) and that the gold contacts are clean and dry.",
        "Lightly wipe the SIM contacts with a soft dry cloth if needed.",
        "Place the SIM back in the tray correctly and reinsert the tray firmly."
      ],
      "why": "Ensures proper contact between the SIM and the phone’s reader."
    },
    {
      "step": 3,
      "title": "Power on and keep Wi‑Fi OFF for testing",
      "instructions": [
        "Turn the phone back ON.",
        "Confirm Wi‑Fi is OFF for this test."
      ],
      "why": "We want to see cellular registration clearly in the status bar."
    },
    {
      "step": 4,
      "title": "Recheck SIM and signal",
      "instructions": [
        "Look at the status bar: do you now see signal bars and a network indicator (4G/LTE/5G)?",
        "In Settings > About phone > SIM/Network status: does it now show the SIM as Active?"
      ],
      "why": "Confirms the phone can detect the SIM and attach to the network."
    }
  ],
  "if_sim_is_now_active": {
    "next_steps": [
      "Ensure Mobile Data = ON and Data Roaming = ON (since you’re in France).",
      "With Wi‑Fi still OFF, try loading a simple site (example.com).",
      "If the site loads, try sending a small photo MMS to your own number.",
      "If MMS still fails after data works, tell me exactly what the status bar shows and we’ll proceed with APN reset and Wi‑Fi Calling/VPN/Data Saver checks."
    ]
  },
  "if_sim_still_missing_after_reseat": {
    "message": "If the phone still reports “No SIM card detected” after a careful reseat, it may be a SIM card or SIM slot hardware issue that requires hands-on assistance or a replacement.",
    "what_we_will_do": "I will transfer you to a human agent for SIM/slot assessment and replacement options.",
    "note": "Before transfer, you can optionally try a second reseat to ensure alignment, but don’t force the tray."
  },
  "what_to_report_back": [
    "After the reseat and power-on: does the status bar show any signal and a 4G/LTE/5G indicator?",
    "In SIM/Network status: does it now show Active, or still Missing?",
    "If Active: could you load a website with Wi‑Fi OFF, and what happened when you tried sending an MMS to yourself?"
  ]
}

