messages.content:
{
  "summary": {
    "current_status": [
      "Your line is active, roaming enabled, with 2 GB added.",
      "Phone shows 5G with mobile data enabled and web browsing works.",
      "MMS still fails to send."
    ],
    "implication": "Since data works, the most likely causes now are MMS-specific settings: app permissions/restrictions, VPN interference, or APN’s MMSC configuration."
  },
  "next_actions_on_your_phone": [
    {
      "step": 1,
      "title": "Run an MMS capability check",
      "how": "Use your device’s diagnostic (can_send_mms) in your support/diagnostics menu if available, or simply try sending a very small photo to yourself and note any error details.",
      "reason": "Confirms the messaging stack can access MMS services."
    },
    {
      "step": 2,
      "title": "Check messaging app permissions",
      "how": "Open Settings > Apps > [Your messaging app] > Permissions. Ensure ‘Storage’ (or ‘Photos/Media’) and ‘SMS’ are allowed.",
      "fix_if_needed": "If not allowed, enable them and retry sending an MMS.",
      "reason": "MMS requires access to media and SMS functions."
    },
    {
      "step": 3,
      "title": "Disable Data Saver and allow unrestricted data for the messaging app",
      "how": "Settings > Network & Internet (or Connections) > Data Saver > turn OFF. Then Settings > Apps > [Messaging] > Mobile data & Wi‑Fi > enable ‘Allow background data’ and ‘Unrestricted data usage’.",
      "reason": "Data Saver/background restrictions can silently block MMS transfers."
    },
    {
      "step": 4,
      "title": "Turn OFF any active VPN",
      "how": "If a VPN app or system VPN is ON, disconnect it. Then retry MMS.",
      "reason": "Some VPNs interfere with MMS routing."
    },
    {
      "step": 5,
      "title": "Verify APN has an MMSC value",
      "how": "Settings > Network & Internet > Mobile network > Access Point Names > tap the active APN. Confirm ‘MMSC’ is populated (not blank).",
      "fix_if_needed": "If MMSC is blank/missing, tap Menu > Reset to default again, then restart the phone.",
      "reason": "MMSC is required specifically for MMS even when general data works."
    },
    {
      "step": 6,
      "title": "Keep Wi‑Fi OFF during the MMS test",
      "how": "Turn Wi‑Fi OFF and ensure Mobile Data + Data Roaming are ON, then send a small photo MMS.",
      "reason": "For some setups, MMS must use mobile data exclusively."
    }
  ],
  "optional_network_checks": [
    {
      "step": 7,
      "title": "Confirm network mode is 4G/5G and stays there",
      "how": "Settings > Network & Internet > Mobile network > Preferred network type > 4G/5G. If it drops to 3G/2G, try manual network selection to a different local carrier, then return to Automatic.",
      "reason": "Ensures adequate bearer for MMS."
    }
  ],
  "what_to_report_back": [
    "Phone type (Android or iPhone) and messaging app name.",
    "Whether Storage/Photos and SMS permissions were already ON or were changed.",
    "Whether Data Saver was ON and if you enabled ‘Unrestricted data’ for the messaging app.",
    "If a VPN was active.",
    "Whether the APN shows an MMSC value.",
    "Exact behavior/error when attempting to send a small photo MMS after these steps."
  ],
  "note": "Given data is working on 5G, fixing permissions/restrictions or confirming MMSC is usually what resolves MMS. I’ll adjust the next steps immediately based on your results."
}

